import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {insightScenario} from '../../server/test/insight-helpers.js';
async function cliContext(scenario,fn,scopes=['*']){
  const created=(await scenario.api('POST','/tokens',{name:'Insight CLI',scopes})).data;
  const cli=args=>new Promise((resolve,reject)=>{
    const child=spawn(process.execPath,[fileURLToPath(new URL('../bin/crew.js',import.meta.url)),...args,'--url',scenario.server.url,'--token',created.token,'--json']);
    let stdout='',stderr='';const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('CLI test deadline'));},10000);
    child.stdout.on('data',chunk=>stdout+=chunk);child.stderr.on('data',chunk=>stderr+=chunk);
    child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);try{resolve({code,data:stdout&&!args.includes('--help')?JSON.parse(stdout):null,stdout,stderr});}catch(error){reject(error);}});
  });
  return fn(cli);
}
test('actual inbox CLI persists cadence reads schedule validates input and enforces scoped auth',()=>insightScenario(s=>cliContext(s,async cli=>{
  const initial=await cli(['inbox','schedule','--org',s.org.id]);assert.equal(initial.code,0,initial.stderr);assert.equal(initial.data.frequency,'manual');
  const enabled=await cli(['inbox','preferences','--org',s.org.id,'--frequency','hourly']);
  assert.equal(enabled.code,0,enabled.stderr);assert.equal(enabled.data.preferences.digestFrequency,'hourly');
  const schedule=await cli(['inbox','schedule','--org',s.org.id]);assert.equal(schedule.data.status,'scheduled');assert(schedule.data.nextRunAt);assert.equal(schedule.data.lastRunAt,null);
  assert.equal((await cli(['inbox','preferences','--org',s.org.id,'--frequency','weekly'])).code,1);
  assert.equal((await cli(['inbox','preferences','--org','other','--frequency','daily'])).code,1);
  const disabled=await cli(['inbox','preferences','--org',s.org.id,'--email','false','--frequency','daily']);assert.equal(disabled.data.preferences.emailEnabled,false);assert.equal(disabled.data.preferences.digestSchedule.status,'disabled');
  assert.equal((await cli(['inbox','preferences','--org',s.org.id,'--frequency','manual'])).data.preferences.digestSchedule.nextRunAt,null);
  assert.match((await cli(['inbox','--help'])).stdout,/15-minute/);
})));
test('actual cadence CLI rejects token missing insight write scope',()=>insightScenario(s=>cliContext(s,async cli=>{
  const result=await cli(['inbox','preferences','--org',s.org.id,'--frequency','daily']);
  assert.equal(result.code,1);assert.match(result.stderr,/scope/);
  assert.equal((await s.api('GET','/notification-preferences?orgId='+s.org.id)).data.preferences.digestFrequency,'manual');
},['insight:read','org:read'])));

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {insightScenario} from '../../server/test/insight-helpers.js';
test('pinned Chromium saves cadence shows next and last run and cancels abandoned organization actions',{timeout:35000},()=>insightScenario(async s=>{
  const other=(await s.api('POST','/orgs',{name:'Other digest organization'})).data.organization;
  await s.member('PATCH','/issues/'+s.issue.id,{title:'Browser digest pending'});
  let child;
  try {
    const result=await new Promise((resolve,reject)=>{
      child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./digest-browser.py',import.meta.url)),JSON.stringify({url:s.server.url,cookie:s.cookie,orgId:s.org.id,otherOrgId:other.id})],{detached:true});
      let stdout='',stderr='';const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Digest browser deadline'));},30000);
      child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);
      child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
    });
    assert.equal(result.code,0,result.stderr);
    const flags=JSON.parse(result.stdout);for(const key of ['manualDefault','allCadences','disabledPreserved','nextLastStatus','orgSwitchAbort','abandonedActionAbort'])assert.equal(flags[key],true,key);
    const a=(await s.api('GET','/notification-preferences?orgId='+s.org.id)).data.preferences;
    const b=(await s.api('GET','/notification-preferences?orgId='+other.id)).data.preferences;
    assert.equal(a.digestFrequency,'daily');assert.equal(b.digestFrequency,'manual');assert.equal(b.digestSchedule.nextRunAt,null);
    assert.equal((await s.api('GET','/digests?orgId='+s.org.id)).data.items[0].count,1);
  } finally {if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}}
}));
